"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[3,5,8],[4,6,10],[5,8,3],[6,10,4],[8,3,6],[10,4,5]];
let variant=OrionProgress.variant('ramp'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,length=2,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function effort(n){return 120/n;}
function setLength(n){if(solved||!Number.isInteger(n)||n<2||n>10)return;length=n;state='ready';render();}
function resetTrial(){length=2;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('ramp')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(length!==challenge())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('ascent');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const run=Math.sqrt(length*length-1),x=35+run*27,y=180-27;return `<svg viewBox="0 0 350 250" role="img" aria-label="${t(`Ramp length ${length} metres, height 1 metre.`,`斜面長 ${length} 米，高 1 米。`)}"><path d="M35 180L${x} ${y}V180Z" fill="#536e72" stroke="#d0b879" stroke-width="4"/><rect x="${x}" y="${y}" width="30" height="27" fill="#64747a"/><g transform="translate(${solved?x-18:40},${solved?y-23:152})"><rect width="26" height="22" rx="3" fill="#d6ab59" stroke="#ffde88"/><path d="M13 0V22" stroke="#64451c"/></g><path d="M${x+36} 180V${y}" stroke="#c9ddd6" stroke-width="2"/><g fill="#f4e9c4" font-size="16"><text x="175" y="35" text-anchor="middle">${t('Treasure weight: 120 N','寶箱重量：120 N')}</text><text x="175" y="215" text-anchor="middle">${t('Sloping length','斜面長度')}: ${length} m</text><text x="${x+38}" y="145" text-anchor="end">1 m</text></g></svg>`;}
function hints(){const q=challenge();return[t('Try a short ramp and a long ramp. Compare the force readings.','試試短斜坡和長斜坡，比較力的讀數。'),t('A longer ramp needs less force, but the treasure travels farther. Choose the shortest length that meets the limit.','斜坡越長，需要的力越小，但寶箱移動的路程越遠。選擇符合上限的最短長度。'),t(`120 ÷ ${q} = ${effort(q)} N. Try ${q} m, then compare with a shorter ramp.`,`120 ÷ ${q} = ${effort(q)} N。試試 ${q} 米，再跟較短斜坡比較。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Ramp Treasury · Orion','斜坡寶庫 · Orion');$('stageTitle').textContent=t(`Delivery ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次運送 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Ramp seals · ${p} / 3`,`斜坡封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('length').value=length;$('length').disabled=solved;$('lengthValue').textContent=length+' m';$('length').setAttribute('aria-valuetext',t(`${length} metres`,`${length} 米`));
$('goal').textContent=t(`Use the shortest whole-metre ramp that needs no more than ${effort(q)} N of pulling force. Height stays 1 m.`,`使用拉力不超過 ${effort(q)} N 的最短整米斜坡。高度維持 1 米。`);$('reading').textContent=state==='ready'?t('Pulling force: test your ramp to measure.','拉力：測試斜坡來量度。'):t(`Pulling force: ${effort(length).toFixed(1)} N · Travel: ${length} m`,`拉力：${effort(length).toFixed(1)} N · 路程：${length} 米`);$('reference').textContent=t('N (newton) measures force. Weight stays 120 N.','N（牛頓）是力的單位。重量維持 120 N。');const messages={ready:['Change the length, then test the ramp.','改變長度，再測試斜坡。'],wrong:[length<q?'Too much force. Try a longer ramp.':'Force fits, but a shorter ramp also works. Save ramp material!',length<q?'所需力太大。試試更長的斜坡。':'拉力符合，但較短的斜坡也可以。節省斜坡材料吧！'],success:['This is the shortest ramp that meets the force limit!','這是符合拉力上限的最短斜坡！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('ascent')?t('Ascent Sigil saved in your collection.','登高符印已存入收藏。'):'';}
$('length').oninput=e=>setLength(Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('ramp',variant);observedVariant=OrionProgress.variant('ramp');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('ascent');render();};function syncProgress(){const v=OrionProgress.variant('ramp'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('ascent')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
